-- 014_seed_itc_forms.sql — Katrina's Inspired To Change agreement wording (2025), as the default form templates.
-- Copied from the ITC Word templates. Practices can add their own templates; these two stay as the starting set.
-- Merge fields in {{double braces}} are filled when a form is sent. See lib/forms.js for the list.
INSERT INTO core.form_templates (name, audience, body) VALUES
  ('Inspired To Change: Client Therapy Agreement', 'adult', $j${"title":"Client Therapy Agreement","audience":"adult","signer_fields":["address","phone"],"intro":["Welcome to Inspired To Change Hypnotherapy","I am looking forward to working with you as your Therapist and because I am serious about ensuring that you achieve the results you want, I have put together this agreement for our therapeutic relationship going forward."],"sections":[{"heading":"The Therapist/Client Relationship","paragraphs":["Solution Focused Therapy is focused on your agenda and your intended outcomes and involves me asking questions, challenging your perspective, suggesting alternative options for consideration, conducting hypnotherapy and offering guidance and support.","Solution Focused Therapy is a collaborative relationship that enables you as the client to gain insight, perspective, clarity, direction, focus and confidence and it relies on commitment and motivation from both the therapist and the client to get the best result.","The number of sessions you will need will depend on the issue you come to me with.  Whilst some clients choose to work with me long after their initial issue is resolved, it is up to you to decide whether you would like further sessions.  It is also up to you to decide, with my help what you would like to achieve and we will agree on outcomes during our first session.","As the client, when you agree to undertake a course of hypnotherapy you also agree to engage with the process.  It is with commitment and partnership working that you will see the best results."]},{"heading":"Confidentiality","paragraphs":["It is inevitable that during the course of our work together you will share with me desires, fears, goals & plans, business/job information and personal/private information, both about yourself, your friends and contacts and about members of your team or family.  I will not, at any time, voluntarily use any such information for my benefit, or disclose this information to a third party.  I may share the essence of our sessions with my Professional Supervisor but will not disclose any information that could identify you.  I will also take the appropriate measures to ensure that any personal information I hold about you is stored securely, in line with GDPR regulations. I am bound to this by the Association for Solution Focused Hypnotherapy code of conduct.","I will not voluntarily disclose that we are in a therapeutic relationship without your expressed permission.  This means that if I see you out and about and we do not have a relationship other than our therapeutic one, I will not approach or acknowledge you, unless you do so first.","Should I feel I need to breach this confidentiality agreement for any reason, I will discuss it with you first and obtain your permission.  The only exception to this is if I believe that you are a danger to yourself or others or am required to by the Association for Solution Focused Hypnotherapy code of conduct.","On occasion, I may disclose information about myself which will always be for the sole purpose of enabling you to make changes in your mindset and your life.  It is important that you also keep this information between us."]},{"heading":"Misunderstandings","paragraphs":["Part of my role as your therapist is to challenge your perspective.  This is essential as often we are unable to see alternative options or view-points without external input.  I will always apply sensitivity and will only ever seek to enable a shift for you so that you can make the changes you desire.  However, humans are imperfect and should I say or do something that upsets you in anyway, you have my permission to tell me either in the moment, or if you prefer, to email or call me after the session.","Openness, transparency, honesty and trust are essential. I am fully committed to your success, so it is important that you support me in supporting you."]},{"heading":"Ending the Relationship","paragraphs":["If you arrive for treatment under the influence of alcohol or mind altering drugs, I will have no choice but to terminate the session immediately and the full fee shall be charged. Further sessions will be at my discretion and may be cancelled permanently.  If I think you would benefit from being referred to another therapist or specialist we will agree to make the referral as soon as possible.","I reserve the right to cancel therapy at any time and to refuse prospective clients at my own discretion."]},{"heading":"Sessions","paragraphs":["Your next appointment will be arranged at the end of each session.  If you would prefer to book more than one session in advance, this is possible too.","Each session will be {{session_format}}, and will last up to one hour.  It is really important that you arrive on time to ensure that you gain the most from the session."]},{"heading":"Missed Sessions","paragraphs":["Life is imperfect and things crop up which can get in the way of therapy.  I will always endeavour to accommodate your needs and to reschedule sessions should you need to.  However, because I have many clients to accommodate I operate a 48 hour cancellation policy.  This means that I require 48 hours’ notice to reschedule a session.  Equally, in the very unlikely event that I should need to reschedule, I will also endeavour to provide 24 hours’ notice where possible."]},{"heading":"Fees and Payment","paragraphs":["My fees for Hypnotherapy are {{fee}} per session.  However, I also offer Hypnotherapy packages for specific issues and we will agree how you would prefer to pay for your therapy at your first session.","Fees are payable by cash, credit card, cheque or BACs at your first session if you have selected a Hypnotherapy package, or on the day of each session if you have selected to pay as you go."]},{"heading":"Inspired to Change Wellbeing Tracker","paragraphs":["At Inspired to Change we use a Wellbeing Tool and Wellbeing Tracker to collect and store basic data from our clients. This basic data includes age, gender, presenting issues, sleep issues and wellbeing outcome scores.","Our Wellbeing Tool provides wellbeing data for each client which enables us to track individual progress whilst undertaking Solution Focused Hypnotherapy (SFH) sessions. We only collect information about wellbeing rather than symptom reduction because research suggests that symptom reduction alone does not encourage wellbeing in the long term.","In addition to providing evidence to individual clients about their progress, collation of this information across all Inspired to Change Associates (on our Inspired To Change Wellbeing Tracker) ensures that we generate meaningful data to evidence the effectiveness of SFH. All data in anonymised and individual clients cannot be identified by anyone other than the Inspired To Change Associate they are working with.","Consent can be withdrawn at any time and you can also request a copy of your data at any time.","Please speak to your local Inspired To Change Associate if you have any questions."]}],"choices":[{"key":"tracker","type":"yesno","required":true,"label":"Do you consent to your anonymised data to be stored and reported on using our Inspired To Change Wellbeing Tracker to demonstrate the effectiveness of Solution Focused Hypnotherapy."},{"key":"newsletter","type":"tick","required":false,"label":"Please tick the box if you would like to receive a copy of my monthly email newsletter with tips and interesting articles on how to live a happy, stress free life."}],"signing_intro":"Please complete this section to reflect your understanding of this therapy agreement.","closing":["Your privacy is important to us and we will not share your personal identifiable information with a third party."],"footer":["My details","{{therapist_name}}","{{therapist_qualifications}}","{{therapist_address}}","{{therapist_postcode}}","{{therapist_phone}}","{{therapist_email}}"]}$j$::jsonb),
  ('Inspired To Change: Parental Consent Form', 'child', $j${"title":"Parental Consent Form","audience":"child","signer_fields":["relationship","address","phone"],"intro":["Welcome to Inspired To Change Hypnotherapy","I am looking forward to working with your child as their Therapist and because I am serious about ensuring that you achieve the results you want for your child, I have put together this agreement for the therapeutic relationship going forward."],"sections":[{"heading":"The Therapist/Client Relationship","paragraphs":["Solution Focused Therapy for children is a collaborative relationship with the whole family that enables your child to gain insight, perspective, clarity, direction, focus and confidence and it relies on commitment and motivation from both the therapist, the child and the whole family to get the best result.","It is important that when you agree to undertake a course of hypnotherapy on your child’s behalf that they agree to engage with the process and that they want to make changes.  It is with commitment and partnership working that we will see the best results."]},{"heading":"Confidentiality","paragraphs":["It is inevitable that during the course of our work together you and your child will share with me desires, fears, goals & plans, and personal/private information, both about yourself, your friends and contacts and about members of your team or family.  I will not, at any time, voluntarily use any such information for my benefit, or disclose this information to a third party.  I may share the essence of our sessions with my Professional Supervisor but will not disclose any information that could identify you.  I will also take the appropriate measures to ensure that any personal information I hold about you is stored securely, in line with GDPR regulations. I am bound to this by the Association for Solution Focused Hypnotherapy code of conduct.","I will not voluntarily disclose that we are in a therapeutic relationship without your expressed permission.  This means that if I see you, your child or any family member out and about and we do not have a relationship other than our therapeutic one, I will not approach or acknowledge you, unless you do so first.","Should I feel I need to breach this confidentiality agreement for any reason, I will discuss it with you first and obtain your permission.  The only exception to this is if I believe that your child is a danger to themselves or others or am required to by the Association for Solution Focused Hypnotherapy code of conduct."]},{"heading":"Misunderstandings","paragraphs":["Part of my role as a therapist is to challenge perspectives.  This is essential as often we are unable to see alternative options or view-points without external input.  I will always apply sensitivity and will only ever seek to enable a shift to help your child make the changes they desire.  However, humans are imperfect and should I say or do something that upsets you or your child in anyway, you have my permission to tell me either in the moment, or if you prefer, to email or call me after the session.","Openness, transparency, honesty and trust are essential. I am fully committed to the success of your child, so it is important that you support me in supporting you."]},{"heading":"Ending the Relationship","paragraphs":["The number of sessions your child will need will depend on the issue they come to me with.  Whilst some people choose to work with me long after their initial issue is resolved, it is up to you as a family to decide whether you would like further sessions.","If I think you would benefit from being referred to another therapist or specialist we will agree to make the referral as soon as possible.","I reserve the right to cancel therapy at any time and to refuse prospective clients at my own discretion."]},{"heading":"Sessions","paragraphs":["Your next appointment will be arranged at the end of each session.  If you would prefer to book more than one session in advance, this is possible too.","Each session will be {{session_format}}, and will last up to one hour.  It is really important that you arrive on time to ensure that you gain the most from the session."]},{"heading":"Missed Sessions","paragraphs":["Life is imperfect and things crop up which can get in the way of therapy.  I will always endeavour to accommodate your needs and to reschedule sessions should you need to.  However, because I have many clients to accommodate I operate a 48 hour cancellation policy.  This means that I require 48 hours’ notice to reschedule a session.  Equally, in the very unlikely event that I should need to reschedule, I will also endeavour to provide 24 hours’ notice where possible."]},{"heading":"Fees and Payment","paragraphs":["My fees for Hypnotherapy are {{fee}} per session.  However, I also offer hypnotherapy packages for specific issues and we will agree how you would prefer to pay for your therapy at your first session.","Fees are payable by cash, credit card, cheque or BACs at your first session if you have selected a Hypnotherapy package, or on the day of each session if you have selected to pay as you go."]},{"heading":"Inspired to Change Wellbeing Tracker","paragraphs":["At Inspired to Change we use a Wellbeing Tool and Wellbeing Tracker to collect and store basic data from our clients. This basic data includes age, gender, presenting issues, sleep issues and wellbeing outcome scores.","Our Wellbeing Tool provides wellbeing data for each client which enables us to track individual progress whilst undertaking Solution Focused Hypnotherapy (SFH) sessions. We only collect information about wellbeing rather than symptom reduction because research suggests that symptom reduction alone does not encourage wellbeing in the long term.","In addition to providing evidence to individual clients about their progress, collation of this information across all Inspired to Change Associates (on our Inspired To Change Wellbeing Tracker) ensures that we generate meaningful data to evidence the effectiveness of SFH. All data in anonymised and individual clients cannot be identified by anyone other than the Inspired To Change Associate they are working with.","Consent can be withdrawn at any time and you can also request a copy of your child’s data at any time.","Please speak to your local Inspired To Change Associate if you have any questions."]},{"heading":"Consent","paragraphs":["I hereby give consent for {{client_name}} to receive Solution Focused Hypnotherapy with {{therapist_name}}. I confirm that I have discussed this with them and they have agreed to take part in the sessions."]}],"choices":[{"key":"tracker","type":"yesno","required":true,"label":"Do you consent to your anonymised data to be stored and reported on using our Inspired To Change Wellbeing Tracker to demonstrate the effectiveness of Solution Focused Hypnotherapy."},{"key":"newsletter","type":"tick","required":false,"label":"Please tick the box if you would like to receive a copy of my monthly email newsletter with tips and interesting articles on how to live a happy, stress free life."}],"signing_intro":"Please complete this section to reflect your understanding of this therapy agreement.","closing":["Your privacy is important to us and we will not share your personal identifiable information with a third party."],"footer":["My details","{{therapist_name}}","{{therapist_qualifications}}","{{therapist_address}}","{{therapist_postcode}}","{{therapist_phone}}","{{therapist_email}}"]}$j$::jsonb);
